import { readFile, writeFile } from "node:fs/promises";
import { assembleGMOptions } from "../src/engine/gm/books.mjs";
import { equipmentPickerEntries } from "../src/engine/trapping-groups.mjs";

const library = JSON.parse(
  await readFile(new URL("../public/data/book-library.json", import.meta.url)),
);
const entries = equipmentPickerEntries(assembleGMOptions(library));
const groups = Object.groupBy(entries, (entry) => entry.trappingPath[0]);
const cell = (value) => String(value).replaceAll("|", "\\|");
const lines = [
  "# Bestiary trapping groups",
  "",
  "Generated by `node scripts/audit-trapping-groups.mjs`; do not edit the inventory by hand. Verify with `node scripts/audit-trapping-groups.mjs --check`.",
  "",
  `${entries.length} distinct picker entries across ${Object.keys(groups).length} primary types. Exact-name duplicates keep the existing weapon → armour → gear → market precedence and saved catalogue IDs. Bucklers and ironfists also appear under Armour & shields → Shields, using the same entry ID.`,
  "",
  "These are browsing labels, not new rules. Weapons retain their printed Melee/Ranged and Skill group. Armour uses existing profiles; the Ithiltaen Helm is an armour reference without an invented AP value. Core gear follows the supplied table sections (pp. 308–311 and 316), with reviewed item groups for travel, lighting and leisure. Supplement categories and explicit item mappings cover the remaining entries. Unprinted prices, weights and profiles stay unresolved. New unmatched entries remain reachable under Other trappings and fail the grouping regression until reviewed.",
  "",
  "| Primary type | Entries |",
  "| --- | ---: |",
  ...Object.entries(groups)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([name, rows]) => `| ${cell(name)} | ${rows.length} |`),
  "",
];
for (const [name, rows] of Object.entries(groups).sort(([a], [b]) =>
  a.localeCompare(b),
)) {
  lines.push(
    `## ${name}`,
    "",
    "| Item | Filter path(s) | Catalogue ID | Source page |",
    "| --- | --- | --- | --- |",
    ...rows.map(
      (entry) =>
        `| ${cell(entry.name)} | ${cell(entry.trappingPaths.map((path) => path.join(" → ")).join("; "))} | ${entry.key} | ${entry.source.book} p. ${entry.source.page} |`,
    ),
    "",
  );
}
const report = lines.join("\n");
const target = new URL("../docs/TRAPPING-GROUPS.md", import.meta.url);
if (process.argv.includes("--check")) {
  if ((await readFile(target, "utf8")) !== report)
    throw Error("Regenerate docs/TRAPPING-GROUPS.md.");
} else await writeFile(target, report);
console.log(
  `Trapping groups: ${entries.length} entries; ${entries.filter((entry) => entry.trappingPath[0] === "Other trappings").length} unreviewed.`,
);
